use hy_check::{check_file, Verdict}; use hy_syntax::parse_file;
#[test] fn interproc_slot_loan_a3_and_const_mutations() { for (s, c) in [("struct acct { bal int }\nfn set_five(m map[string]acct) { p := &m[\"a\"]\np.bal = 500 }\nfn main() { m := map[string]acct{\"a\": acct{bal: 10}}\nn := &m[\"a\"]\nn.bal = 99\nset_five(m)\n_ = n.bal }", "HYB-E3102"), ("struct acct { bal int }\nstruct eng { m map[string]acct }\nfn (e *eng) bump() { p := &e.m[\"a\"]\np.bal = 500 }\nfn main() { e := eng{m: map[string]acct{\"a\": acct{bal: 10}}}\nn := &e.m[\"a\"]\nn.bal = 99\ne.bump()\n_ = n.bal }", "HYB-E3102"), ("struct acct { bal int }\nfn main() { m := map[string]acct{\"a\": acct{bal: 10}}\nn := &m[\"a\"]\nn.bal = 99\nf := fn() { p := &m[\"a\"]\np.bal = 500 }\nf()\n_ = n.bal }", "HYB-E3102"), ("struct acct { bal int }\nconst global_m = map[string]acct{\"a\": acct{bal: 10}}\nfn touch(m map[string]acct) int { p := &m[\"a\"]\nreturn p.bal }\nfn main() { _ = touch(global_m) }", "HYB-E3006")] { let r = check_file(&parse_file("t.hy", s).unwrap()); assert_eq!(r.verdict, Verdict::Reject, "{s}"); assert!(r.diagnostics.iter().any(|d| d.code == c), "{s}: {:?}", r.diagnostics); } for s in ["struct acct { bal int }\nfn copy_read(m map[string]acct) int { x := m[\"a\"]\nx.bal = 500\nreturn x.bal }\nfn main() { m := map[string]acct{\"a\": acct{bal: 10}}\nn := &m[\"a\"]\nn.bal = 99\n_ = copy_read(m)\n_ = n.bal }", "struct acct { bal int }\nfn set_five(m map[string]acct) { p := &m[\"a\"]\np.bal = 500 }\nfn main() { m := map[string]acct{\"a\": acct{bal: 10}}\nn := &m[\"a\"]\nn.bal = 99\nset_five(m) }"] { assert_eq!(check_file(&parse_file("t.hy", s).unwrap()).verdict, Verdict::Accept, "{s}"); } }
